m","name":"SEC企业申报文件","tier":"primary"}],"note":"同一宏泰东街浦项中心楼名，非单塔独立命名。","sub":5},{"id":"1669ffe8-f07c-44da-882b-b359b18fa155","f":"name_en","type":"text","value":"East Gate Plaza","unit":"name","sources":[{"url":"https://wri.org.cn/en/about/contact","name":"世界资源研究所办公地址","tier":"primary"},{"url":"https://webresource.ctrip.com/code/engpurehtml/footer/contact.html","name":"携程办公地址","tier":"primary"}],"note":"东中街9号，英文项目名称一致。","sub":5},{"id":"84ffb230-ae43-41ee-a15d-bd03e63c0ba1","f":"parking_total","type":"integer","value":585,"unit":"count","sources":[{"url":"https://www.dongxuguoji.cn/","name":"东旭国际中心项目资料","tier":"secondary"},{"url":"https://www.bjttlj.cn/detail-43.html","name":"北京智慧商务选址","tier":"secondary"}],"note":"四栋项目合计585；公开资料地上地下划分有矛盾，因此仅填总数。","sub":5},{"id":"84ffb230-ae43-41ee-a15d-bd03e63c0ba1","f":"metro_access","type":"text","value":"地铁9号线丰台科技园站","unit":"nearby_station","sources":[{"url":"https://www.bjttlj.cn/detail-43.html","name":"北京智慧商务选址","tier":"secondary"},{"url":"https://www.fang.com/xiaoqu/bj-1010829035/","name":"房天下楼盘资料","tier":"secondary"}],"note":"同一园区，记录共同支持站名，不记录距离或排除其他站点。","sub":5},{"id":"d6dbe652-fb9b-4eef-85b1-330620e41ba5","f":"efficiency_rate","type":"numeric","value":70,"unit":"percent","sources":[{"url":"https://www.bjjingfang.com/index/lease/detail?id=10961","name":"北京京房楼宇资料","tier":"secondary"},{"url":"https://www.sbzszx.com/productinfo/56579.html","name":"商办招商楼宇资料","tier":"secondary"}],"note":"同一远洋锐中心写字楼，公开招商使用率约70%，非现场测量。","sub":5},{"id":"80dec004-1daf-43b3-a545-071a3fc3b023","f":"name_en","type":"text","value":"Ping An International Financial Center","unit":"name","sources":[{"url":"https://www.reedexport.cn/zh-cn/contact-us.html","name":"励展博览集团办公地址","tier":"primary"},{"url":"https://en.thcapital.com.cn/contactus/","name":"华控基金办公地址","tier":"primary"}],"note":"新源南路1-3号A、B座办公地址共同确认项目英文名称。","sub":5}]$ext$::jsonb) v(id uuid,f text,type text,value jsonb,unit text,sources jsonb,note text,sub int)),
v AS (SELECT a.*,d.id actual_target,b.id actual_building,to_jsonb(d)->a.f actual_value, p.n source_rows,p.good good_source_rows,p.urls urls,
 CASE WHEN a.kind='internal_archived_page' THEN EXISTS (SELECT 1 FROM arch s JOIN public.project_material_library l ON l.id=s.lib JOIN public.project_material_library_pages pg ON pg.extraction_id=l.id AND pg.page_number=s.pg AND pg.content_sha256=s.hash CROSS JOIN LATERAL (SELECT (regexp_match(pg.content->>'native_text',s.pat))[1] val) m WHERE s.name=b.name AND s.f=a.f AND s.sub=(a.details->>'sub_batch')::int AND s.lib::text=a.details->>'source_record_id' AND 'page:'||s.pg=a.details->>'source_field' AND s.unit=a.details->>'unit' AND m.val IS NOT NULL AND CASE s.type WHEN 'numeric' THEN to_jsonb(m.val::numeric*s.mult) WHEN 'integer' THEN to_jsonb(m.val::integer) WHEN 'boolean' THEN to_jsonb(true) ELSE to_jsonb(trim(regexp_replace(m.val,'[[:space:]]+',' ','g'))) END=a.new_values->a.f AND EXISTS (SELECT 1 FROM public.building_data_field_provenance p WHERE p.evidence_group_id=a.ev AND p.is_current AND position('page_sha256='||s.hash in p.evidence_note)>0))
 WHEN a.kind='internal_field_extraction' THEN a.details->>'source_record_id'=d.id::text AND a.details->>'source_field'='power_system' AND ((a.f='power_source' AND d.power_system LIKE '市政双路供电%' AND a.new_values->>a.f='市政双路供电') OR (a.f='power_backup_generator' AND a.new_values->>a.f=(regexp_match(d.power_system,'(大厦应急柴油发电机组[0-9]+台，其中[0-9]+台为租户预留)'))[1]))
 WHEN a.kind='external_cross_verified' THEN EXISTS (SELECT 1 FROM ext s WHERE s.id=d.id AND s.f=a.f AND s.sub=(a.details->>'sub_batch')::int AND s.value=a.new_values->a.f AND s.unit=a.details->>'unit' AND s.sources=a.details->'source_urls' AND (SELECT count(*) FROM jsonb_array_elements(s.sources) x WHERE x->>'url'=ANY(p.urls))=a.expected_sources AND cardinality(p.urls)=a.expected_sources)
 ELSE false END source_manifest_matches
 FROM a LEFT JOIN public.building_brochure_data d ON d.id::text=a.target_id AND d.building_id=a.bid LEFT JOIN public.buildings b ON b.id=d.building_id
 LEFT JOIN LATERAL (SELECT count(*) n,count(*) FILTER(WHERE p.building_id=a.bid AND p.brochure_data_id=d.id AND p.target_table=a.target_table AND p.field_name=a.f AND p.evidence_group_id=a.ev AND p.field_value=a.new_values->a.f AND p.is_current AND p.value_recorded_at IS NOT NULL AND p.source_retrieved_at IS NOT NULL AND p.evidence_note LIKE 'batch_ref=ai_building_field_backfill_20261125_v5_100;%' AND p.verification_status=a.details->>'verification_status' AND (CASE WHEN a.kind='external_cross_verified' THEN p.source_type='internet' AND nullif(trim(p.source_url),'') IS NOT NULL AND p.verification_status='cross_verified' ELSE p.source_type IN ('brochure','other') AND p.verification_status='legacy_backfill' END)) good,array_agg(p.source_url) FILTER(WHERE p.source_url IS NOT NULL) urls FROM public.building_data_field_provenance p WHERE p.building_id=a.bid AND p.target_table=a.target_table AND p.field_name=a.f AND p.is_current) p ON true),
checks AS (SELECT *,actual_target IS NOT NULL AND actual_building IS NOT NULL AND target_table='building_brochure_data' AND old_values->f='null'::jsonb AND new_values->f IS NOT NULL AND new_values->f<>'null'::jsonb AND actual_value=new_values->f AND user_id='codex' AND actor_kind='tool' AND details->>'ai_assisted'='true' AND source_rows=expected_sources AND good_source_rows=expected_sources AND source_manifest_matches AS verified FROM v)
SELECT count(*) actual_audits,count(DISTINCT (target_table,target_id,f)) unique_fields,count(DISTINCT bid) buildings,count(DISTINCT f) field_types,count(*) FILTER(WHERE verified) verified_fields,count(*) FILTER(WHERE verified IS DISTINCT FROM true) failed_fields,coalesce(sum(good_source_rows),0) matched_provenance_rows,(SELECT count(*) FROM public.building_data_field_provenance p WHERE p.is_current AND p.evidence_note LIKE 'batch_ref=ai_building_field_backfill_20261125_v5_100;%') current_batch_provenance_rows,(SELECT count(*) FROM public.audit_logs WHERE action_type='AI_FIELD_ROLLBACK' AND details->>'rollback_batch_ref'='ai_building_field_backfill_20261125_v5_100_rollback') persistent_rollback_audits,(SELECT count(*) FROM public.audit_logs old JOIN a ON old.target_table=a.target_table AND old.target_id=a.target_id AND (old.details->>'field_name'=a.f OR old.new_values ? a.f) WHERE old.action_type='AI_FIELD_FILL' AND old.details->>'batch_ref' IS DISTINCT FROM 'ai_building_field_backfill_20261125_v5_100') other_batch_duplicate_audits,
 (SELECT jsonb_object_agg(f,n ORDER BY f) FROM (SELECT f,count(*) n FROM a GROUP BY f) z) field_counts,
 (SELECT jsonb_object_agg(kind,n) FROM (SELECT kind,count(*) n FROM a GROUP BY kind) z) source_counts,
 (SELECT jsonb_object_agg(sub,n) FROM (SELECT details->>'sub_batch' sub,count(*) n FROM a GROUP BY 1) z) batch_counts,
 (SELECT jsonb_agg(jsonb_build_object('audit_id',id,'field',f,'target_id',target_id)) FROM checks WHERE verified IS DISTINCT FROM true) failures
FROM checks;
